/* Mobile-first: стили для мобильных, потом добавляем для больших */
.sidebar {
  display: none;
}

@media (min-width: 768px) {
  .sidebar {
    display: block;
    width: 250px;
  }
}

/* Desktop-first: стили для десктопа, потом «обрезаем» для мобильных */
.sidebar {
  display: block;
  width: 250px;
}

@media (max-width: 767px) {
  .sidebar {
    display: none;
  }
}

/* Типичные breakpoints */
/* Мобильные: < 640px */
/* Планшеты: 640px — 1024px */
/* Десктопы: > 1024px */

.container {
  padding: 1rem;        /* mobile */
}

@media (min-width: 640px) {
  .container {
    padding: 1.5rem;    /* планшет */
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 2rem;      /* десктоп */
  }
}

/* === Базовый (мобильный) === */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

/* === Планшеты === */
@media (min-width: 640px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }
}

/* === Десктопы === */
@media (min-width: 1024px) {
  .grid {
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
  }
}

/* Мобильные: 1 колонка */
.grid {
  grid-template-columns: 1fr;
}

/* Планшет: 2 колонки */
@media (min-width: 640px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
}

/* Маленький десктоп: 3 колонки */
@media (min-width: 1024px) {
  .grid { grid-template-columns: repeat(3, 1fr); }
}

/* Большой десктоп: 4 колонки */
@media (min-width: 1280px) {
  .grid { grid-template-columns: repeat(4, 1fr); }
}

/* Светлая тема (по умолчанию) */
body {
  background: white;
  color: #333;
}

/* Тёмная тема */
@media (prefers-color-scheme: dark) {
  body {
    background: #1a1a2e;
    color: #e0e0e0;
  }
}

/* Обычная анимация */
.fade-in {
  animation: fadeIn 0.5s ease-in;
}

/* Если пользователь просит уменьшить движение */
@media (prefers-reduced-motion: reduce) {
  .fade-in {
    animation: none;
  }
}
